<script setup>
import { onBeforeUnmount, onMounted, ref } from 'vue';
import { api, formatCost, formatDate, formatNumber } from '../api.js';
import EmptyState from '../components/EmptyState.vue';
import UiIcon from '../components/UiIcon.vue';
const section = ref('requests'), logs = ref([]), blocked = ref([]), keys = ref([]), providers = ref([]), loading = ref(true), page = ref(1), pages = ref(1), total = ref(0), expanded = ref(null);
const filters = ref({ key_id: '', provider_id: '', status: '' });
async function load() { loading.value = true; const query = new URLSearchParams({ page: page.value, ...Object.fromEntries(Object.entries(filters.value).filter(([, value]) => value)) }); const data = await api('GET', `/api/admin/usage?${query}`); logs.value = data.logs; pages.value = data.pages; total.value = data.total; loading.value = false; }
async function loadBlocked() { blocked.value = (await api('GET', '/api/admin/blocked')).logs; }
function apply() { page.value = 1; load(); }
function move(delta) { page.value += delta; load(); }
function refresh() { load(); loadBlocked(); }
onMounted(async () => { await refresh(); const [k, p] = await Promise.all([api('GET', '/api/admin/keys'), api('GET', '/api/admin/providers')]); keys.value = k.keys; providers.value = p.providers; window.addEventListener('relay-refresh', refresh); });
onBeforeUnmount(() => window.removeEventListener('relay-refresh', refresh));
const formatHeaders = (headers) => JSON.stringify(headers, null, 2);
</script>
<template>
  <div class="settings-subnav logs-subnav" role="tablist" aria-label="日志分类"><button :class="{ active: section === 'requests' }" @click="section = 'requests'"><UiIcon name="logs" :size="16" />请求日志</button><button :class="{ active: section === 'blocked' }" @click="section = 'blocked'"><UiIcon name="shield" :size="16" />拦截记录</button></div>
  <section v-if="section === 'requests'" class="panel"><header class="panel-header log-header"><div><h2>请求审计 <span class="count">{{ total }}</span></h2><p>按 Key、供应商或执行结果筛选调用记录</p></div><div class="log-filters"><select v-model="filters.key_id" @change="apply"><option value="">全部 Key</option><option v-for="key in keys" :key="key.id" :value="key.id">{{ key.name }}</option></select><select v-model="filters.provider_id" @change="apply"><option value="">全部供应商</option><option v-for="provider in providers" :key="provider.id" :value="provider.id">{{ provider.name }}</option></select><select v-model="filters.status" @change="apply"><option value="">全部状态</option><option value="success">成功</option><option value="error">失败</option></select></div></header><div v-if="loading" class="table-loading">正在查询日志…</div><EmptyState v-else-if="!logs.length" title="没有匹配的请求" text="调整筛选条件，或发起一次 API 调用后再查看。" /><div v-else class="table-wrap"><table class="logs-table"><thead><tr><th>时间 / 请求 ID</th><th>Key / 供应商</th><th>模型</th><th>Token（入 / 出）</th><th>费用</th><th>延迟</th><th>状态</th><th></th></tr></thead><tbody v-for="log in logs" :key="log.id"><tr><td><div>{{ formatDate(log.created_at) }}</div><code class="request-id">{{ log.request_id.slice(0, 8) }}</code></td><td><div>{{ log.key_name || '已删除 Key' }}</div><small class="muted">{{ log.provider_name || '已删除供应商' }}</small></td><td><code class="model-name">{{ log.model || '—' }}</code></td><td>{{ formatNumber(log.prompt_tokens) }} / {{ formatNumber(log.completion_tokens) }}</td><td>{{ formatCost(log.cost_micros / 1e6) }}</td><td>{{ formatNumber(log.latency_ms) }} ms</td><td><span class="badge" :class="log.status < 400 ? 'success' : 'danger'">{{ log.status }}</span></td><td><button v-if="log.error" class="icon-button" @click="expanded = expanded === log.id ? null : log.id"><UiIcon name="info" :size="16" /></button></td></tr><tr v-if="expanded === log.id" class="error-detail"><td colspan="8">{{ log.error }}</td></tr></tbody></table></div><footer class="pagination"><span>第 {{ page }} / {{ pages }} 页</span><div><button class="button small" :disabled="page <= 1" @click="move(-1)">上一页</button><button class="button small" :disabled="page >= pages" @click="move(1)">下一页</button></div></footer></section>
  <section v-else class="panel"><header class="panel-header"><div><h2>客户端拦截记录 <span class="count">{{ blocked.length }}</span></h2><p>仅保留最近 5 小时，每小时自动清理；Authorization、x-api-key 和 Cookie 已脱敏</p></div><button class="button small" @click="loadBlocked"><UiIcon name="refresh" :size="15" />刷新</button></header><EmptyState v-if="!blocked.length" icon="shield" title="暂无拦截记录" text="User-Agent 不匹配的请求会显示在这里。" /><div v-else class="table-wrap"><table class="logs-table blocked-table"><thead><tr><th>时间</th><th>Key / 供应商</th><th>模型</th><th>IP</th><th>User-Agent</th><th>请求头</th></tr></thead><tbody><tr v-for="log in blocked" :key="log.id"><td>{{ formatDate(log.created_at) }}</td><td><div>{{ log.key_name || '已删除 Key' }}</div><small class="muted">{{ log.provider_name || '已删除供应商' }}</small></td><td><code class="model-name">{{ log.model }}</code></td><td><code>{{ log.ip }}</code></td><td class="ua-cell">{{ log.user_agent || '未知' }}</td><td><details><summary>查看</summary><pre class="header-detail">{{ formatHeaders(log.headers) }}</pre></details></td></tr></tbody></table></div></section>
</template>
